  "labels": [
    {
      "label": "T_PlayingByAppointment",
      "span": "it said 2Days left. Now just logged in after sleeping and the event is now changed.",
      "rationale": "The game imposed a time-limited event schedule that changed the available reward opportunity when the player returned."
    }
