  "labels": [
    {
      "label": "T_DailyRewards",
      "span": "can't get my daily rewards unless I bet 50,000 with out it I can't complete my daily rewards",
      "rationale": "The game provides daily rewards but makes them conditional on completing a required daily activity."
    },
    {
